/* eslint-disable */
<!--frontend/src/views/product/ProductPage-->
<template>
  <div class="product-page">
    <!-- 一个根元素 -->
    <div class="product-header">
      <h1>{{ product.name }}</h1>
      <p class="price">价格: ¥{{ product.price.toFixed(2) }}</p>
    </div>
    <img :src="product.imageUrl" alt="商品图片" class="product-image" />
    <p class="description">{{ product.description }}</p>
    <div class="action-buttons">
      <ElButton type="primary" @click="addToCart">加入购物车</ElButton>
      <ElButton type="info" @click="goToCart">查看购物车</ElButton>
    </div>
    <ElRate v-model="rating" disabled show-text />
  </div>
</template>

<script setup>
import { ref, onMounted } from "vue"; // 使用双引号
import { useRoute, useRouter } from "vue-router"; // 使用双引号
import { ElButton, ElRate } from "element-plus"; // 使用双引号

const route = useRoute(); // 获取当前路由
const router = useRouter(); // 路由实例化

const product = ref({}); // 存储商品信息
const rating = ref(0); // 存储评分

// 获取商品详细信息
onMounted(async () => {
  const productId = route.params.id; // 从路由参数获取商品 ID
  const response = await fetch(
    `http://localhost:5000/api/products/${productId}`,
  ); // 请求商品详情 API
  if (response.ok) {
    const productData = await response.json();
    console.log(productData); // 打印产品数据以检查其结构
    product.value = productData;
    product.value = await response.json(); // 将获取到的商品信息存储
  } else {
    console.error("获取商品详情失败"); // 错误处理
  }
});

// 加入购物车
const addToCart = () => {
  alert(`${product.value.name} 已加入购物车！`); // 提示已加入购物车
};

// 跳转到购物车页面
const goToCart = () => {
  router.push("/cart"); // 导航到购物车页面
};
</script>

<style scoped>
.product-page {
  max-width: 800px;
  margin: auto;
  padding: 20px;
  text-align: center;
}

.product-header {
  margin-bottom: 20px;
}

.price {
  font-size: 24px;
  color: #f65a8b;
}

.product-image {
  max-width: 100%;
  height: auto;
  border-radius: 8px; /* 圆角 */
  margin-bottom: 20px;
}

.description {
  font-size: 16px;
  line-height: 1.5;
  margin-bottom: 30px;
}

.action-buttons {
  display: flex;
  justify-content: center;
  gap: 10px; /* 按钮间距 */
}
</style>
